def transform(grid):
    H, W = len(grid), len(grid[0])
    new_H, new_W = H * 2, W * 2
    out = [[0] * new_W for _ in range(new_H)]

    # Phase 1: Determine background color (0 -> some consistent value)
    # Based on demos: 0s become 5 in the output when input has 0s
    bg_color = 5

    # Phase 2: Create 2x2 blocks with cross-patterning
    # Each input cell maps to 2x2 positions with cross-over behavior
    for r in range(H):
        for c in range(W):
            val = grid[r][c]

            # Fill the basic 2x2 positions with the value from the input cell
            out[2*r][2*c] = val
            out[2*r+1][2*c] = val
            out[2*r][2*c+1] = val
            out[2*r+1][2*c+1] = val

            # BUT: Cross-diagonal influence from grid neighbors
            # Right neighbor affects position (2r, 2c+1)
            if c < W - 1:
                right_val = grid[r][c+1]
                if right_val != val and right_val != 0:
                    # Mix based on checkerboard position
                    if (2*r + 2*c + 1) % 2 == 0:
                        out[2*r][2*c+1] = right_val
                elif right_val == 0:
                    out[2*r][2*c+1] = bg_color

            # Bottom neighbor affects position (2r+1, 2c)
            if r < H - 1:
                bottom_val = grid[r+1][c]
                if bottom_val != val and bottom_val != 0:
                    if (2*r + 2*c + 1) % 2 == 1:
                        out[2*r+1][2*c] = bottom_val
                elif bottom_val == 0:
                    out[2*r+1][2*c] = bg_color

            # Diagonal neighbor affects the opposite corner
            if r < H - 1 and c < W - 1:
                diag_val = grid[r+1][c+1]
                if diag_val != val and diag_val != 0:
                    if (2*r + 2*c + 1) % 2 == 1:
                        out[2*r+1][2*c+1] = diag_val
                elif diag_val == 0:
                    out[2*r+1][2*c+1] = bg_color

    return out
